/**
 * colblitz_v4.cpp — Optimal DP policy lookup for /sphere quest (oq).
 *
 * Policy file
 * -----------
 *   Filename : quest_policy_v4_20260628_200909.bin.lzma
 *   Size     : ~324 MB compressed / ~3.30 GB decompressed (299,883,616 entries)
 *   SHA-256  : 2382ca5bafd0a20a456619512d44ed38b0a628d3d1a47b9b72bc294a4d31393b
 *   Source   : /home/colblitz/projects/cortana3/scripts/precompute_quest_policy_v4.cpp
 *
 *   Generated by an exact Bellman DP over all C(25,4)=12,650 boards with D4
 *   symmetry canonicalization.  The file contains one 11-byte entry per
 *   reachable canonical observation state, sorted ascending by packed key
 *   (lo:uint64, hi:uint16) for binary search.
 *
 * Binary format
 * -------------
 *   [4 bytes LE uint32]  num_entries
 *   per entry (11 bytes):
 *     [8 bytes LE uint64]  lo       — cells  0–20, 3 bits each
 *     [2 bytes LE uint16]  hi       — cells 21–24, 3 bits each
 *     [1 byte   int8]      best_cell — cell index 0–24, in CANONICAL frame
 *
 * Observation encoding (3 bits per cell):
 *   0 = hidden, 1 = blue(0nb), 2 = teal(1nb), 3 = green(2nb),
 *   4 = yellow(3nb), 5 = orange(4+nb), 6 = purple (spP or spR)
 *
 * Lookup protocol
 * ---------------
 *   1. Build obs[25] from current board state.
 *   2. Find canonical D4 transform t that yields lex-min packed key.
 *   3. Binary-search sorted entries for (lo, hi).
 *   4. Un-transform best_cell from canonical → original frame.
 *   5. If not found: fall back to MIXED(alpha=1.0, beta=0.1) heuristic.
 *
 * Algorithm
 * ---------
 *   Priority order in next_click():
 *     1. spR visible and unclicked  → click it (150 SP for 1 budget click).
 *     2. spP visible and unclicked  → click it (free; 5 SP each).
 *     3. All 4 purples known        → post-red greedy (highest-value non-purple).
 *     4. Policy lookup              → optimal DP cell.
 *     5. Fallback (state not found) → MIXED heuristic (P(purple) + Gini).
 *
 * Memory usage
 * ------------
 *   ~3.30 GB heap at init_evaluation_run() time (loaded once, shared across
 *   all games via run-level member variable).
 */

#pragma GCC optimize("O3,unroll-loops")

#include <algorithm>
#include <array>
#include <cassert>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>

#include <lzma.h>

#include "../../interface/strategy.h"

using namespace sphere;

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

static constexpr int N_CELLS   = 25;
static constexpr int N_PURPLES = 4;
static constexpr int GRID      = 5;
static constexpr int N_MASKS   = 12650;  // C(25,4)

static constexpr double ALPHA = 1.0;
static constexpr double BETA  = 0.1;

static constexpr int VAL_B = 10;
static constexpr int VAL_T = 20;
static constexpr int VAL_G = 35;
static constexpr int VAL_Y = 55;
static constexpr int VAL_O = 90;
static constexpr int VAL_R = 150;

// ---------------------------------------------------------------------------
// Color enum
// ---------------------------------------------------------------------------

enum Color : uint8_t {
    COL_UNK = 0,
    COL_P   = 1,
    COL_R   = 2,
    COL_B   = 3,
    COL_T   = 4,
    COL_G   = 5,
    COL_Y   = 6,
    COL_O   = 7,
};

static inline Color parse_color(const std::string& s) {
    if (s.size() < 3) return COL_UNK;
    switch (s[2]) {
        case 'P': return COL_P;
        case 'R': return COL_R;
        case 'B': return COL_B;
        case 'T': return COL_T;
        case 'G': return COL_G;
        case 'Y': return COL_Y;
        case 'O': return COL_O;
        default:  return COL_UNK;
    }
}

// Maps Color → observation encoding used by the policy (0–6)
// COL_UNK=0(hidden), COL_P=6, COL_R=6, COL_B=1, COL_T=2, COL_G=3, COL_Y=4, COL_O=5
static constexpr uint8_t COLOR_TO_OBS[8] = { 0, 6, 6, 1, 2, 3, 4, 5 };

static constexpr int NB_COUNT_FOR_COLOR[8] = { 0, 0, 0, 0, 1, 2, 3, 4 };
static constexpr int COLOR_VALUE[8]        = { 0, 0, VAL_R, VAL_B, VAL_T, VAL_G, VAL_Y, VAL_O };

// ---------------------------------------------------------------------------
// Geometry tables (filled once)
// ---------------------------------------------------------------------------

static uint32_t NB_MASK[N_CELLS];
static uint32_t ALL_MASKS[N_MASKS];
static bool     g_geometry_ready = false;

static void init_geometry() {
    if (g_geometry_ready) return;
    for (int r = 0; r < GRID; ++r)
        for (int c = 0; c < GRID; ++c) {
            uint32_t m = 0;
            for (int dr = -1; dr <= 1; ++dr)
                for (int dc = -1; dc <= 1; ++dc) {
                    if (dr == 0 && dc == 0) continue;
                    int nr = r + dr, nc = c + dc;
                    if (nr >= 0 && nr < GRID && nc >= 0 && nc < GRID)
                        m |= 1u << (nr * GRID + nc);
                }
            NB_MASK[r * GRID + c] = m;
        }
    int idx = 0;
    for (int a = 0; a < N_CELLS; ++a)
    for (int b = a+1; b < N_CELLS; ++b)
    for (int c = b+1; c < N_CELLS; ++c)
    for (int d = c+1; d < N_CELLS; ++d)
        ALL_MASKS[idx++] = (1u<<a)|(1u<<b)|(1u<<c)|(1u<<d);
    g_geometry_ready = true;
}

// ---------------------------------------------------------------------------
// D4 symmetry permutation tables
// ---------------------------------------------------------------------------
//
// g_perm[t][src] = dst   — where src maps TO under transform t
// g_inv_perm[t][dst] = src — inverse
//
//   T0  identity:         r,c → r,   c
//   T1  rot 90 CW:        r,c → c,   4-r
//   T2  rot 180:          r,c → 4-r, 4-c
//   T3  rot 270 CW:       r,c → 4-c, r
//   T4  flip H (l↔r):     r,c → r,   4-c
//   T5  flip V (u↔d):     r,c → 4-r, c
//   T6  flip main diag:   r,c → c,   r
//   T7  flip anti-diag:   r,c → 4-c, 4-r

static int g_perm[8][N_CELLS];
static int g_inv_perm[8][N_CELLS];
static bool g_d4_ready = false;

static void init_d4() {
    if (g_d4_ready) return;
    for (int r = 0; r < GRID; ++r) {
        for (int c = 0; c < GRID; ++c) {
            int src = r * GRID + c;
            g_perm[0][src] = r         * GRID + c;
            g_perm[1][src] = c         * GRID + (4 - r);
            g_perm[2][src] = (4 - r)   * GRID + (4 - c);
            g_perm[3][src] = (4 - c)   * GRID + r;
            g_perm[4][src] = r         * GRID + (4 - c);
            g_perm[5][src] = (4 - r)   * GRID + c;
            g_perm[6][src] = c         * GRID + r;
            g_perm[7][src] = (4 - c)   * GRID + (4 - r);
        }
    }
    for (int t = 0; t < 8; ++t)
        for (int i = 0; i < N_CELLS; ++i)
            g_inv_perm[t][g_perm[t][i]] = i;
    g_d4_ready = true;
}

// ---------------------------------------------------------------------------
// Policy entry layout (11 bytes, matches binary file)
// ---------------------------------------------------------------------------

#pragma pack(push, 1)
struct PolicyEntry {
    uint64_t lo;        // cells  0–20, 3 bits each
    uint16_t hi;        // cells 21–24, 3 bits each
    int8_t   best_cell; // canonical cell index 0–24
};
#pragma pack(pop)
static_assert(sizeof(PolicyEntry) == 11, "PolicyEntry must be 11 bytes");

// ---------------------------------------------------------------------------
// Packed key operations
// ---------------------------------------------------------------------------

static inline void pack_obs(const uint8_t obs[N_CELLS],
                             uint64_t& lo, uint16_t& hi) {
    lo = 0;
    for (int i = 0; i <= 20; ++i)
        lo |= ((uint64_t)obs[i]) << (i * 3);
    hi = 0;
    for (int i = 21; i < N_CELLS; ++i)
        hi |= ((uint16_t)obs[i]) << ((i - 21) * 3);
}

// Apply D4 transform t: result[perm[t][i]] = src[i]
static inline void apply_obs_transform(int t, const uint8_t src[N_CELLS],
                                        uint8_t dst[N_CELLS]) {
    for (int i = 0; i < N_CELLS; ++i)
        dst[g_perm[t][i]] = src[i];
}

// Returns canonical transform index and writes out (canon_lo, canon_hi)
static inline int canonical_transform(const uint8_t obs[N_CELLS],
                                       uint64_t& best_lo, uint16_t& best_hi) {
    uint8_t tmp[N_CELLS];
    apply_obs_transform(0, obs, tmp);
    pack_obs(tmp, best_lo, best_hi);
    int best_t = 0;
    for (int t = 1; t < 8; ++t) {
        apply_obs_transform(t, obs, tmp);
        uint64_t tlo; uint16_t thi;
        pack_obs(tmp, tlo, thi);
        if (tlo < best_lo || (tlo == best_lo && thi < best_hi)) {
            best_lo = tlo; best_hi = thi;
            best_t = t;
        }
    }
    return best_t;
}

// ---------------------------------------------------------------------------
// Policy binary search
// ---------------------------------------------------------------------------

// entries_ is sorted ascending by (lo, hi).
static inline int policy_lookup(const PolicyEntry* entries, uint32_t n_entries,
                                 uint64_t lo, uint16_t hi) {
    uint32_t left = 0, right = n_entries;
    while (left < right) {
        uint32_t mid = left + (right - left) / 2;
        const PolicyEntry& e = entries[mid];
        if (e.lo < lo || (e.lo == lo && e.hi < hi)) {
            left = mid + 1;
        } else if (e.lo == lo && e.hi == hi) {
            return (int)(int8_t)e.best_cell;
        } else {
            right = mid;
        }
    }
    return -1;  // not found
}

// ---------------------------------------------------------------------------
// LZMA decompression helper
// ---------------------------------------------------------------------------

static std::vector<uint8_t> lzma_decompress_file(const std::string& path) {
    FILE* f = fopen(path.c_str(), "rb");
    if (!f) {
        fprintf(stderr, "[colblitz_v4] ERROR: cannot open %s\n", path.c_str());
        std::exit(1);
    }
    fseek(f, 0, SEEK_END);
    long file_size = ftell(f);
    fseek(f, 0, SEEK_SET);

    std::vector<uint8_t> compressed(file_size);
    if ((long)fread(compressed.data(), 1, file_size, f) != file_size) {
        fprintf(stderr, "[colblitz_v4] ERROR: short read from %s\n", path.c_str());
        fclose(f);
        std::exit(1);
    }
    fclose(f);

    // Read num_entries from the first 4 bytes after decompression to pre-size
    // the output buffer.  We decompress in a streaming pass with a generous
    // initial guess and resize if needed.

    lzma_stream strm = LZMA_STREAM_INIT;
    lzma_ret ret = lzma_stream_decoder(&strm, UINT64_MAX, LZMA_CONCATENATED);
    if (ret != LZMA_OK) {
        fprintf(stderr, "[colblitz_v4] ERROR: lzma_stream_decoder failed: %d\n", (int)ret);
        std::exit(1);
    }

    // Initial decompressed buffer: read only the 4-byte header first, then
    // re-run with the correct size.
    // For simplicity: decompress in large chunks, appending to output.
    std::vector<uint8_t> out;
    out.reserve((size_t)3'400'000'000ULL);  // ~3.4 GB hint

    static constexpr size_t CHUNK = 64 * 1024 * 1024;  // 64 MB output chunks
    std::vector<uint8_t> chunk(CHUNK);

    strm.next_in   = compressed.data();
    strm.avail_in  = (size_t)file_size;

    for (;;) {
        strm.next_out  = chunk.data();
        strm.avail_out = CHUNK;

        ret = lzma_code(&strm, LZMA_FINISH);
        size_t produced = CHUNK - strm.avail_out;
        out.insert(out.end(), chunk.data(), chunk.data() + produced);

        if (ret == LZMA_STREAM_END) break;
        if (ret != LZMA_OK) {
            fprintf(stderr, "[colblitz_v4] ERROR: lzma_code failed: %d\n", (int)ret);
            lzma_end(&strm);
            std::exit(1);
        }
    }
    lzma_end(&strm);
    return out;
}

// ---------------------------------------------------------------------------
// Global policy table — shared across all strategy instances (threads)
// ---------------------------------------------------------------------------
//
// The harness instantiates one strategy object per thread.  Loading 3.3 GB
// per instance would OOM on typical hardware.  We therefore load the policy
// exactly once into a process-wide static and point every instance at it.

static std::vector<PolicyEntry> g_entries;
static uint32_t                 g_n_entries = 0;
static bool                     g_policy_loaded = false;

static void load_policy_once() {
    if (g_policy_loaded) return;
    g_policy_loaded = true;  // set before work so re-entrant calls (if any) short-circuit

    std::string path = std::string(REPO_ROOT)
                       + "/data/quest_policy_v4_20260628_200909.bin.lzma";

    fprintf(stderr, "[colblitz_v4] loading policy: %s\n", path.c_str());

    std::vector<uint8_t> raw = lzma_decompress_file(path);

    if (raw.size() < 4) {
        fprintf(stderr, "[colblitz_v4] ERROR: decompressed data too small (%zu bytes)\n",
                raw.size());
        std::exit(1);
    }

    uint32_t n_entries;
    std::memcpy(&n_entries, raw.data(), 4);

    size_t expected = (size_t)4 + (size_t)n_entries * 11;
    if (raw.size() < expected) {
        fprintf(stderr,
                "[colblitz_v4] ERROR: decompressed size %zu < expected %zu\n",
                raw.size(), expected);
        std::exit(1);
    }

    g_n_entries = n_entries;
    g_entries.resize(n_entries);
    std::memcpy(g_entries.data(), raw.data() + 4, (size_t)n_entries * 11);

    fprintf(stderr, "[colblitz_v4] policy loaded: %u entries (%.2f GB)\n",
            g_n_entries, (double)(g_n_entries * 11) / 1e9);
}

// ---------------------------------------------------------------------------
// Strategy class
// ---------------------------------------------------------------------------

class ColblitzV4OQStrategy : public OQStrategy {
public:
    ColblitzV4OQStrategy() {
        init_geometry();
        init_d4();
    }

    // -----------------------------------------------------------------------
    // init_evaluation_run — load policy file (called once before all games)
    // -----------------------------------------------------------------------

    void init_evaluation_run() override {
        load_policy_once();
    }

    // -----------------------------------------------------------------------
    // init_game_payload — reset per-game state
    // -----------------------------------------------------------------------

    void init_game_payload(const std::string& /*meta_json*/) override {
        n_surviving_ = N_MASKS;
        std::memcpy(surviving_, ALL_MASKS, sizeof(uint32_t) * N_MASKS);
        std::memset(known_color_,    0, sizeof(known_color_));
        std::memset(known_revealed_, 0, sizeof(known_revealed_));
    }

    // -----------------------------------------------------------------------
    // next_click
    // -----------------------------------------------------------------------

    void next_click(const std::vector<Cell>& board,
                    const std::string& /*meta_json*/,
                    ClickResult& out) override
    {
        // ------------------------------------------------------------------
        // 1. Parse board into flat arrays
        // ------------------------------------------------------------------
        bool  clicked[N_CELLS]     = {};
        Color board_color[N_CELLS] = {};

        for (const Cell& c : board) {
            int idx = c.row * GRID + c.col;
            clicked[idx]     = c.clicked;
            board_color[idx] = parse_color(c.color);
        }

        // ------------------------------------------------------------------
        // 2. Update surviving masks with newly revealed cells
        // ------------------------------------------------------------------
        for (int i = 0; i < N_CELLS; ++i) {
            Color col = board_color[i];
            if (!known_revealed_[i] && col != COL_UNK) {
                known_revealed_[i] = true;
                known_color_[i]    = col;
                filter_masks(i, col);
            }
        }

        // ------------------------------------------------------------------
        // 3. Classify cells
        // ------------------------------------------------------------------
        int unclicked[N_CELLS];
        int n_unclicked = 0;
        int clicked_purples[N_PURPLES + 1];
        int n_clicked_purples = 0;
        int red_cell          = -1;  // unclicked spR
        int red_clicked_idx   = -1;  // already-clicked spR

        for (int i = 0; i < N_CELLS; ++i) {
            if (!clicked[i]) {
                unclicked[n_unclicked++] = i;
                if (board_color[i] == COL_R) red_cell = i;
            } else {
                if (board_color[i] == COL_P)
                    clicked_purples[n_clicked_purples++] = i;
                else if (board_color[i] == COL_R)
                    red_clicked_idx = i;
            }
        }

        // ------------------------------------------------------------------
        // 4. Phase 1: click visible red immediately
        // ------------------------------------------------------------------
        if (red_cell >= 0) {
            out.row = red_cell / GRID;
            out.col = red_cell % GRID;
            return;
        }

        // ------------------------------------------------------------------
        // 5. Phase 2: click any visible unclicked purple (free)
        // ------------------------------------------------------------------
        for (int i = 0; i < n_unclicked; ++i) {
            int idx = unclicked[i];
            if (board_color[idx] == COL_P) {
                out.row = idx / GRID;
                out.col = idx % GRID;
                return;
            }
        }

        if (n_unclicked == 0) { out.row = 0; out.col = 0; return; }

        // ------------------------------------------------------------------
        // 6. Phase 3: post-red greedy — all 4 purples known
        // ------------------------------------------------------------------
        int n_all_purples = n_clicked_purples + (red_clicked_idx >= 0 ? 1 : 0);
        if (n_all_purples == N_PURPLES) {
            uint32_t purple_mask = 0;
            for (int k = 0; k < n_clicked_purples; ++k)
                purple_mask |= 1u << clicked_purples[k];
            if (red_clicked_idx >= 0)
                purple_mask |= 1u << red_clicked_idx;

            int best = post_red_greedy(unclicked, n_unclicked, purple_mask);
            if (best < 0) best = unclicked[0];
            out.row = best / GRID; out.col = best % GRID;
            return;
        }

        // ------------------------------------------------------------------
        // 7. Phase 4: policy lookup
        // ------------------------------------------------------------------
        if (!g_entries.empty()) {
            // Build obs[25]
            uint8_t obs[N_CELLS] = {};
            for (int i = 0; i < N_CELLS; ++i) {
                Color col = board_color[i];
                if (col == COL_UNK) {
                    obs[i] = 0;  // hidden
                } else {
                    obs[i] = COLOR_TO_OBS[col];
                }
            }

            // Canonicalize
            uint64_t clo; uint16_t chi;
            int t = canonical_transform(obs, clo, chi);

            // Binary search
            int canon_cell = policy_lookup(g_entries.data(), g_n_entries, clo, chi);

            if (canon_cell >= 0 && canon_cell < N_CELLS) {
                // Un-transform back to original frame
                int orig_cell = g_inv_perm[t][canon_cell];
                // Safety: must be unclicked
                if (!clicked[orig_cell]) {
                    out.row = orig_cell / GRID;
                    out.col = orig_cell % GRID;
                    return;
                }
            }
        }

        // ------------------------------------------------------------------
        // 8. Phase 5: MIXED fallback
        // ------------------------------------------------------------------
        int best = mixed_search(unclicked, n_unclicked);
        out.row = best / GRID;
        out.col = best % GRID;
    }

private:
    // -----------------------------------------------------------------------
    // Per-game state
    // -----------------------------------------------------------------------

    uint32_t surviving_[N_MASKS];
    int      n_surviving_ = 0;
    bool     known_revealed_[N_CELLS];
    Color    known_color_[N_CELLS];

    // -----------------------------------------------------------------------
    // filter_masks — Minesweeper-style in-place compaction
    // -----------------------------------------------------------------------

    void filter_masks(int cell_idx, Color col) {
        uint32_t cell_bit = 1u << cell_idx;
        if (col == COL_P || col == COL_R) {
            int out = 0;
            for (int i = 0; i < n_surviving_; ++i)
                if (surviving_[i] & cell_bit)
                    surviving_[out++] = surviving_[i];
            n_surviving_ = out;
        } else {
            int k       = NB_COUNT_FOR_COLOR[col];
            uint32_t nb = NB_MASK[cell_idx];
            int out = 0;
            for (int i = 0; i < n_surviving_; ++i) {
                uint32_t m = surviving_[i];
                if (!(m & cell_bit) && __builtin_popcount(m & nb) == k)
                    surviving_[out++] = m;
            }
            n_surviving_ = out;
        }
    }

    // -----------------------------------------------------------------------
    // post_red_greedy
    // -----------------------------------------------------------------------

    int post_red_greedy(const int* unclicked, int n_unclicked,
                        uint32_t purple_mask) const
    {
        static constexpr Color nb_to_col[5] = {COL_B, COL_T, COL_G, COL_Y, COL_O};
        int best_idx = -1, best_val = -1;
        for (int i = 0; i < n_unclicked; ++i) {
            int ci = unclicked[i];
            if ((purple_mask >> ci) & 1) continue;
            int nb = __builtin_popcount(purple_mask & NB_MASK[ci]);
            if (nb > 4) nb = 4;
            int val = COLOR_VALUE[nb_to_col[nb]];
            if (val > best_val) { best_val = val; best_idx = ci; }
        }
        return best_idx;
    }

    // -----------------------------------------------------------------------
    // mixed_search — ALPHA*P(purple) + BETA*Gini
    // -----------------------------------------------------------------------

    int mixed_search(const int* unclicked, int n_unclicked) const
    {
        if (n_unclicked == 0) return 0;
        if (n_surviving_ == 0) return unclicked[0];

        int oc[N_CELLS][6] = {};
        for (int mi = 0; mi < n_surviving_; ++mi) {
            uint32_t mask = surviving_[mi];
            for (int i = 0; i < n_unclicked; ++i) {
                int ci = unclicked[i];
                if ((mask >> ci) & 1u) {
                    oc[ci][0]++;
                } else {
                    int nb = __builtin_popcount(mask & NB_MASK[ci]);
                    if (nb > 4) nb = 4;
                    oc[ci][nb + 1]++;
                }
            }
        }

        double inv_n     = 1.0 / (double)n_surviving_;
        int    best_idx  = unclicked[0];
        double best_score = -1.0;

        for (int i = 0; i < n_unclicked; ++i) {
            int ci = unclicked[i];
            double p_purple = oc[ci][0] * inv_n;
            double sum_sq   = 0.0;
            for (int c = 0; c < 6; ++c) {
                double p = oc[ci][c] * inv_n;
                sum_sq += p * p;
            }
            double score = ALPHA * p_purple + BETA * (1.0 - sum_sq);
            if (score > best_score) { best_score = score; best_idx = ci; }
        }
        return best_idx;
    }
};

// ---------------------------------------------------------------------------
// C exports — Style A (template style)
// ---------------------------------------------------------------------------

extern "C" sphere::StrategyBase* create_strategy()                         { return new ColblitzV4OQStrategy(); }
extern "C" void                  destroy_strategy(sphere::StrategyBase* s) { delete s; }

extern "C" void strategy_init_evaluation_run(void* inst) {
    static_cast<ColblitzV4OQStrategy*>(inst)->init_evaluation_run();
}

extern "C" void strategy_init_game_payload(void* inst, const char* meta_json) {
    static_cast<ColblitzV4OQStrategy*>(inst)->init_game_payload(
        meta_json ? meta_json : "{}");
}

extern "C" const char* strategy_next_click(void* inst,
                                            const char* board_json,
                                            const char* meta_json)
{
    thread_local static std::string buf;
    auto* s = static_cast<ColblitzV4OQStrategy*>(inst);

    std::vector<Cell> board = parse_board_json(board_json);
    ClickResult out;
    s->next_click(board, meta_json ? meta_json : "{}", out);

    buf = "{\"row\":" + std::to_string(out.row) +
          ",\"col\":" + std::to_string(out.col) + "}";
    return buf.c_str();
}
